import{_ as t,o,c as r,a2 as a}from"./chunks/framework.BM5YPQmL.js";const u=JSON.parse('{"title":"Alpha status","description":"","frontmatter":{},"headers":[],"relativePath":"alpha-status.md","filePath":"alpha-status.md","lastUpdated":1793784412000}'),s={name:"alpha-status.md"};function d(n,e,i,c,l,h){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="alpha-status" tabindex="-1">Alpha status <a class="header-anchor" href="#alpha-status" aria-label="Permalink to &quot;Alpha status&quot;">​</a></h1><p>kernl is a first draft. This page says what runs, what is a contract without an implementation, and which upstream gaps are open. It is updated in the same pull request as the code it describes.</p><h2 id="what-works" tabindex="-1">What works <a class="header-anchor" href="#what-works" aria-label="Permalink to &quot;What works&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>Package</th><th>State</th></tr></thead><tbody><tr><td>Guard</td><td><code>@kernl/guard</code></td><td>Three profiles (<code>createGuardConfig</code>, <code>applyNappletRules</code>), envelope classification, ingress flood control with quarantine, visibility gate, focus-aware firewall over <code>@kehto/firewall</code>&#39;s <code>evaluate()</code>, the fixed zero-network CSP, a port of kehto&#39;s unreleased nested-frame lock (<a href="./decisions#d-014">D-014</a>), eleven mitigation descriptions for the UI. Pure, fully specified in <code>packages/guard/features/</code>.</td></tr><tr><td>Messaging</td><td><code>@kernl/messaging</code></td><td><code>MessagingProvider</code>, <code>MessagingBackend</code>, <code>MessagingRegistry</code> with saved-preference restore, the composite backend with <code>provider:innerId</code> namespacing, <code>describeProvider</code> rows, a complete in-memory backend (<code>createMemoryBackend</code>) used by the preview and the tests, and three providers (<code>private</code>, <code>legacy</code>, <code>ratchet</code>) built with <code>defineProvider</code> from backends the shell injects. The network backends for <code>private</code> and <code>legacy</code> are in <code>@kernl/core</code> (<code>createPrivateMessagesBackend</code>, <code>createLegacyMessagesBackend</code>) and are wired in the live shell (<a href="#messaging-providers-in-the-live-shell">below</a>).</td></tr><tr><td>Bridges</td><td><code>@kernl/bridges</code></td><td><code>Locator</code> parsing for the web schemes, <code>magnet:</code>, <code>nzb:</code>, <code>slsk:</code> and <code>mailto:</code>, the <code>Bridge</code> contract, the registry with its <code>authorize</code> hook and outcome events, a complete HTTP bridge with SSRF policy, the four backend-driven bridges up to their backend interface, <code>createHandoffBackends</code>, which serves all four by opening the locator in an app on the user&#39;s device, <code>createBridgeResourceResolver</code> for kehto&#39;s resource service, and <code>describeBridge</code> rows.</td></tr><tr><td>Composition</td><td><code>@kernl/core</code></td><td><code>createKernl</code> over one applesauce <code>EventStore</code>, <code>RelayPool</code> and <code>AccountManager</code>, with kehto&#39;s real <code>createShellBridge</code> exercised end to end in <code>kernl.feature</code>: an applet is decoded, resolved, planned and mounted, binds its port through the guarded <code>handleWindowMessage</code>, completes <code>shell.ready</code>, is answered by the theme, identity and resource services, and is quarantined and revoked when it floods. Relay tiers, the applesauce adapters, the guard pipeline and runtime firewall rules, grants over <code>bridge.runtime.aclState</code>, consent summaries, the default registries and the layouts each have their own feature file.</td></tr><tr><td>Shell UI</td><td><code>apps/web</code></td><td>Landing site at <code>/</code> and the shell at <code>/app/</code>: sign-in (browser extension, remote signer, read-only, password-protected local account), open by address with the required and optional domains as choices, windows, a grants panel per window, a shell-wide guard panel with the event log, the provider picker, and the offline preview behind <code>?preview=1</code> (<a href="./decisions#d-011">D-011</a>), hosted at <a href="https://kernlize.github.io/app/?preview=1" target="_blank" rel="noreferrer">kernlize.github.io/app/?preview=1</a>.</td></tr></tbody></table><p>&quot;Works&quot; means the behaviour has a scenario in <code>packages/*/features/</code>, the scenario passes, and the page describing it exists. It does not mean the API is stable. Every package is <code>0.1.0</code>; on 0.x a breaking change is a minor bump.</p><h2 id="messaging-providers-in-the-live-shell" tabindex="-1">Messaging providers in the live shell <a class="header-anchor" href="#messaging-providers-in-the-live-shell" aria-label="Permalink to &quot;Messaging providers in the live shell&quot;">​</a></h2><p><code>createKernl</code> registers all three providers and, unless <code>KernlOptions.messagingBackends</code> overrides them, wires two real backends from <code>@kernl/core</code>: <code>createPrivateMessagesBackend</code> for <code>private</code> (NIP-17 gift-wrapped messages) and <code>createLegacyMessagesBackend</code> for <code>legacy</code> (NIP-04 direct messages). Both sign and encrypt with the active account&#39;s signer and nothing else (<a href="./decisions#d-015">D-015</a>). Availability follows the active account, and an unavailable provider reports a reason from <code>MESSAGING_UNAVAILABLE_REASONS</code>:</p><table tabindex="0"><thead><tr><th>Provider</th><th>Available when</th><th>Reason otherwise</th></tr></thead><tbody><tr><td><code>private</code></td><td>The active account&#39;s signer exposes <code>nip44</code> (browser extension, remote signer, password-protected local account)</td><td><code>sign-in-required</code> with no active account; <code>signer-cannot-encrypt</code> when the signer has no <code>nip44</code> (a read-only account)</td></tr><tr><td><code>legacy</code></td><td>The active account&#39;s signer exposes <code>nip04</code></td><td><code>sign-in-required</code> with no active account; <code>signer-cannot-encrypt</code> when the signer has no <code>nip04</code></td></tr><tr><td><code>ratchet</code></td><td>Never in this draft</td><td><code>no-runtime</code>: a double-ratchet runtime has to be supplied</td></tr></tbody></table><p><code>private</code> sends to the recipient&#39;s kind 10050 inbox relays, falling back to the sender&#39;s <code>outbox</code> and <code>super</code> tiers when the recipient publishes none, and wraps a copy to the sender so the conversation reads the same on every device. <code>legacy</code> is metadata-exposing: sender, recipient and timing are public on the event, and the picker says so. The Messages panel decrypts the user&#39;s own messages without a consent prompt, because the shell asks on the user&#39;s behalf; an applet reaches messages only through the <code>dm</code> domain grant. The preview still uses the in-memory backend.</p><h2 id="what-does-not-work-yet" tabindex="-1">What does not work yet <a class="header-anchor" href="#what-does-not-work-yet" aria-label="Permalink to &quot;What does not work yet&quot;">​</a></h2><ul><li><strong>In-shell transfer backends.</strong> Downloads, sharing and mail work only by hand-off: <code>createKernl</code> passes <code>host.openLink</code> to <code>createDefaultBridges</code>, so the torrent, NZB, Soulseek and mail bridges open the locator&#39;s canonical address in an app on the user&#39;s device after the user confirms leaving kernl. kernl makes no connection for these; what the device app then does on its own network is outside kernl&#39;s view and control. No backend moves the data inside the shell, and there is no downloads view. A <code>job</code> result from a hand-off is an id, not a transfer kernl can track, and it is reported even when the user declines to leave. See <a href="./concepts/bridges#hand-off-backends">Bridges</a>.</li><li><strong>Ratchet sessions.</strong> No double-ratchet runtime ships, so <code>ratchet</code> reports <code>no-runtime</code> (the table above). See <a href="./concepts/messaging">Messaging</a>.</li><li><strong>Web fetch from the browser shell, beyond the simple case.</strong> The HTTP bridge runs in the page, so it is subject to CORS, and an opaque redirect it cannot inspect is refused with <code>denied:redirect-unverifiable</code>. Web fetch works from the shell for <code>https</code> origins that permit cross-origin reads and answer without a redirect. Hostnames are checked as literals only; no resolver is wired. See <a href="./concepts/bridges#the-http-bridge">Bridges</a>.</li><li><strong>Per-host bridge consent.</strong> <code>createKernl</code> builds the bridge registry with <code>createDefaultBridges()</code> and no <code>authorize</code> hook, so a <code>resource</code> request from a granted applet is checked by the HTTP bridge&#39;s SSRF policy and nothing else. A host that wants a prompt per host or scheme passes its own registry in <code>KernlOptions.bridges</code>.</li><li><strong>Per-applet guard profiles.</strong> <code>GuardFacade.setProfile</code> rebuilds the pipeline for the whole shell and is not persisted. The per-applet, remembered override <a href="./decisions#d-003">D-003</a> describes is not in this draft.</li><li><strong>Mobile layouts beyond the basics.</strong> The layouts are desktop tilings over <code>@kehto/wm</code> (<a href="./concepts/layouts">Layouts</a>). At 720 px wide and below the shell switches to a compact layout: every window fills the desktop, and the bar keeps <strong>Open</strong> and moves the guard, messages, layout, minimised windows, settings and sign-out into a <strong>Menu</strong> sheet; panels open as full-width sheets. There are no gestures.</li><li><strong>Multi-account switching.</strong> <code>AccountManager</code> holds several accounts and the sign-in panel lists them, but switching means signing out and in.</li><li><strong>Grant persistence across devices.</strong> Grants, relay tiers and messaging preferences persist in the host&#39;s storage only. There is no sync. Every key is listed in <a href="./concepts/persistence">Persistence</a>.</li><li><strong>Packages on npm.</strong> The <code>@kernl/*</code> packages are not published; they are used from a clone of the source repository, which is private during the alpha. See <a href="./packages/#install">Packages</a>.</li><li><strong>Source links in the API reference.</strong> <code>typedoc.json</code> sets <code>packageOptions.disableSources: true</code>, so the generated reference has no &quot;Defined in&quot; source links. They would point at the source repository, which is private during the alpha.</li></ul><p>The <a href="./roadmap">Roadmap</a> orders this list.</p><h2 id="upstream-gaps" tabindex="-1">Upstream gaps <a class="header-anchor" href="#upstream-gaps" aria-label="Permalink to &quot;Upstream gaps&quot;">​</a></h2><p>kernl composes kehto rather than forking it (<a href="./decisions#d-001">D-001</a>). Four seams in kehto are narrower than kernl wants. All four are filed upstream against <code>kehto/web</code> rather than patched locally (<a href="https://github.com/kehto/web/issues/397" target="_blank" rel="noreferrer">#397</a>, <a href="https://github.com/kehto/web/issues/398" target="_blank" rel="noreferrer">#398</a>, <a href="https://github.com/kehto/web/issues/399" target="_blank" rel="noreferrer">#399</a>, <a href="https://github.com/kehto/web/issues/400" target="_blank" rel="noreferrer">#400</a>). Each has a kernl layer that shrinks when it lands (<a href="./decisions#d-012">D-012</a>):</p><ol><li><strong><code>ShellAdapter</code> does not forward <code>getFocusContext</code>, <code>onFirewallEvent</code> or <code>firewallPersistence</code> to the runtime.</strong> Without <code>getFocusContext</code> the runtime firewall treats every window as focused. kernl runs its focus-aware firewall in <code>@kernl/guard</code>, in front of the bridge for the window-level <code>hello</code> and as an observer of port traffic, using the pure <code>evaluate()</code> engine with visibility supplied by the host; what it rejects on port traffic is refused before dispatch (gap 3). Because that layer never supplies <code>initElapsedMs</code>, kehto&#39;s init-burst guard does not fire there, and the guard config&#39;s <code>burstGuard</code> is unused. The runtime does supply it, so the runtime&#39;s own startup burst guard (kehto&#39;s default, 20 operations in the first 3 s, <code>block</code>) refuses before dispatch. Without <code>onFirewallEvent</code> the runtime&#39;s refusals reach the applet as <code>firewall:</code> errors but not the host, so the guard panel shows kernl&#39;s own count of the same rates. (<a href="https://github.com/kehto/web/issues/397" target="_blank" rel="noreferrer">kehto/web#397</a>)</li><li><strong><code>createRuntime</code> hardcodes the ACL default policy to <code>&#39;permissive&#39;</code>.</strong> kernl produces its restrictive posture with <code>KernlGrants.ensure</code>, which writes an explicit grant or revoke for every capability of every applet it plans, plus <code>capabilities.resolveEnvironment</code>, which narrows the advertised domains to the baseline and the user&#39;s grants. The permissive default is never reached for an applet kernl runs. (<a href="https://github.com/kehto/web/issues/398" target="_blank" rel="noreferrer">kehto/web#398</a>)</li><li><strong>There is no hook that can hold or delay port traffic.</strong> kehto calls <code>onNappletMessage</code> synchronously before it dispatches each envelope, but ignores its answer. kernl closes the refusal half of this gap itself: whenever its ingress guard, focus firewall or hidden-window check will not let an envelope through (a size cap, a burst above the per-second rate, the smaller unfocused budget, or a non-control request from a window that is not visible), it sets the applet&#39;s runtime policy to <code>deny</code> for that one synchronous dispatch (<code>refuseCurrentDispatch</code>), so kehto refuses the envelope with a <code>firewall:</code> error. Quarantine revokes the binding inside the hook, so kehto finds no session and drops the envelope that crossed the limit. Control envelopes are never refused. What remains is the gentler half: a hidden window&#39;s requests are refused, and the applet must retry once visible, where a hook that let the shell defer them would hold them instead. See <a href="./concepts/guard#where-enforcement-happens">Guard</a>. (<a href="https://github.com/kehto/web/issues/399" target="_blank" rel="noreferrer">kehto/web#399</a>)</li><li><strong>The runtime firewall never applies an unfocused multiplier.</strong> Because of gap 1 the runtime sees every window as focused, so its multiplier, whatever the value, never applies; and <code>FirewallStateContainer</code> has no setter for <code>unfocusedMultiplier</code>, so kernl could not install the profile&#39;s value even if focus were forwarded. The profile&#39;s value is applied only by kernl&#39;s focus firewall, whose overruns kernl refuses through <code>refuseCurrentDispatch</code>. (<a href="https://github.com/kehto/web/issues/400" target="_blank" rel="noreferrer">kehto/web#400</a>)</li></ol><p>A fifth observation, not a gap kernl needs closed: the transport internals <code>createNip5dTransport</code> and <code>createShellReadyState</code> are not exported, so kernl uses <code>createShellBridge</code> unchanged.</p><p>One mitigation is carried locally rather than waiting upstream: <code>@kehto/shell</code> 0.29.0 leaves an applet free to create a child frame whose fresh realm still has WebRTC, and the lock that closes this exists only on kehto main behind <code>experimental.nestedContextLock</code>. <code>@kernl/guard</code> ports it and <code>planMount</code> always applies it, until a kehto release ships the flag (<a href="./decisions#d-014">D-014</a>).</p><h2 id="corrections" tabindex="-1">Corrections <a class="header-anchor" href="#corrections" aria-label="Permalink to &quot;Corrections&quot;">​</a></h2><ul><li><strong>Rate enforcement (corrected 2026-11-03).</strong> Earlier drafts of these docs, the README and D-012 said kehto&#39;s runtime firewall refused envelopes over the profile&#39;s rates. It did not: <code>applyRuntimeFirewallRules</code> also set each applet&#39;s runtime policy to <code>allow</code>, and kehto&#39;s <code>evaluate()</code> returns <code>pass</code> for an <code>allow</code> policy before it looks at any rate, matcher or burst. No rate was refused before dispatch; only kernl&#39;s reports and quarantine applied. The policy call is removed, the rates and kehto&#39;s startup burst guard now refuse before dispatch, and D-012 is rewritten to match.</li><li><strong>Size caps (corrected 2026-11-03).</strong> The guard&#39;s size matchers were described as able to report <code>matcher:size:&lt;class&gt;</code> in the shell. They cannot fire there: the ingress guard rejects the same envelopes first. Oversized downloads and queries were reported but still handled; they are now refused before dispatch.</li><li><strong>Focus tightening, bursts and hidden windows (changed 2026-11-04).</strong> These were reported to the user but still handled. They are now refused before dispatch the same way size caps are (<code>refuseCurrentDispatch</code>): a request over the smaller unfocused budget, a request in a burst above the per-second rate, and any non-control request from a hidden window get a <code>firewall:</code> error. Control envelopes are never refused. See <a href="./decisions#d-012">D-012</a>.</li></ul><h2 id="versions-this-draft-is-built-against" tabindex="-1">Versions this draft is built against <a class="header-anchor" href="#versions-this-draft-is-built-against" aria-label="Permalink to &quot;Versions this draft is built against&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Dependency</th><th>Range</th></tr></thead><tbody><tr><td><code>@kehto/acl</code></td><td><code>^0.20.2</code></td></tr><tr><td><code>@kehto/firewall</code></td><td><code>^0.6.3</code></td></tr><tr><td><code>@kehto/runtime</code></td><td><code>^0.27.2</code></td></tr><tr><td><code>@kehto/shell</code></td><td><code>^0.29.0</code></td></tr><tr><td><code>@kehto/services</code></td><td><code>^0.29.0</code></td></tr><tr><td><code>@kehto/nip</code></td><td><code>^0.8.0</code></td></tr><tr><td><code>@kehto/wm</code></td><td><code>^0.0.2</code></td></tr><tr><td><code>applesauce-*</code></td><td><code>^7.0.x</code></td></tr><tr><td><code>@napplet/core</code></td><td><code>&gt;=0.37.0 &lt;0.38.0</code></td></tr></tbody></table><p>The protocol itself is a draft. NIP-5D is <a href="https://github.com/nostr-protocol/nips/pull/2303" target="_blank" rel="noreferrer">nostr-protocol/nips PR #2303</a> and the NAP documents live at <a href="https://github.com/napplet/naps" target="_blank" rel="noreferrer">napplet/naps</a>. kernl keeps no local copy of either; see <a href="./policies/spec-conformance">Spec conformance</a>.</p>',22)])])}const g=t(s,[["render",d]]);export{u as __pageData,g as default};
